7	
8	// 存储读取异常的回归保障：保护「已有意见数据无法读取时，拒绝保存新意见，并保留原有存储内容」
9	// 这一现有行为。只走公开入口（GET/POST /api/ideas）并直接检查磁盘上的 ideas.json，
10	// 在真实进程上验证两类异常：
11	//   1. 存储内容不是合法 JSON（含被截断、夹着空白与换行的不完整 JSON）；
12	//   2. 是合法 JSON、但顶层不是意见数组（对象、字符串等）。
13	// 两类异常都必须：POST 合法意见返回 500 和现有的 error 说明、响应不带 idea、不能算成 400；
14	// GET 返回现有的 500 错误，不能当成空列表；请求结束后文件内容与请求前逐字节一致
15	// （不能被重写成 []、被格式化、或被替换成只含新意见的列表），也不能留下 .tmp 临时文件。
16	// 发起提交的意见本身三个字段都合法，避免由表单内容错误遮住需要保障的结果。
17	
18	interface Idea {
19	  id: string;
20	  title: string;
21	  description: string;
22	  scenario: string;
23	  createdAt: string;
24	}
25	
26	// 三个字段都符合当前要求的新意见：任何拒绝都只能来自存储读取异常。
27	const NEW_IDEA = {
28	  title: '存储读取异常时的新意见',
29	  description: '这一条意见的标题、详细说明与使用场景都合法，拒绝结果只能来自无法读取已有数据。',
30	  scenario: '需要先恢复历史意见数据的场景',
31	};
32	
33	function freshDir(): string {
34	  return mkdtempSync(join(tmpdir(), 'featureharbor-corrupt-'));
35	}
36	
37	function ideasFile(server: StartedServer): string {
38	  return join(server.dataDir, 'ideas.json');
39	}
40	
41	async function postNewIdea(
42	  server: StartedServer,
43	): Promise<{ status: number; contentType: string | null; text: string; data: any }> {
44	  const res = await fetch(`${server.origin}/api/ideas`, {
45	    method: 'POST',
46	    headers: { 'content-type': 'application/json' },
47	    body: JSON.stringify(NEW_IDEA),
48	  });
49	  const text = await res.text();
50	  let data: any;
51	  try {
52	    data = JSON.parse(text);
53	  } catch {
54	    data = undefined;
55	  }
56	  return { status: res.status, contentType: res.headers.get('content-type'), text, data };
57	}
58	
59	async function getIdeas(
60	  server: StartedServer,
61	): Promise<{ status: number; data: any }> {
62	  const res = await fetch(`${server.origin}/api/ideas`);
63	  return { status: res.status, data: await res.json() };
64	}
65	
66	// 兜底停止：即使重复调用也不挂住测试（stop 内部另有 SIGKILL 兜底）。
67	async function safeStop(server: StartedServer | undefined): Promise<void> {
68	  if (!server) return;
69	  await Promise.race([
70	    server.stop(),
71	    new Promise<void>((resolve) => setTimeout(resolve, 2000)),
72	  ]);
73	}
74	
75	// 两类存储异常的具体内容：既包含无法解析，也包含能解析但顶层不是数组。
76	// 其中刻意放入不完整 JSON、前导/末尾空白与换行，用来验证这些文字逐字节保留。
77	const CORRUPT_CASES: Array<{ name: string; content: string }> = [
78	  {
79	    name: '存储内容不是合法 JSON（写到一半被截断的数组）',
80	    content: '[\n  {"id":"old-1","title":"未保存完的意见","description":"文件写到一半',
81	  },
82	  {
83	    name: '不完整 JSON 中夹杂空白、制表符与换行，末尾也不是合法结尾',
