48	function makeElement(tag: string): El {
49	  const node = {
50	    tagName: tag.toUpperCase(),
51	    className: '',
52	    hidden: false,
53	    value: '',
54	    dateTime: '',
55	    children: [],
56	    text: null as string | null,
57	    innerHTMLAssigned: false,
58	    listeners: {} as Record<string, Array<(event: unknown) => unknown>>,
59	    append(...nodes: El[]): void {
60	      this.children.push(...nodes);
61	    },
62	    replaceChildren(...nodes: El[]): void {
63	      this.children = [...nodes];
64	    },
65	    addEventListener(type: string, fn: (event: unknown) => unknown): void {
66	      (this.listeners[type] ??= []).push(fn);
67	    },
68	    reset(): void {},
69	  };
70	  Object.defineProperty(node, 'textContent', {
71	    get(this: any): string {
72	      return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join('');
73	    },
74	    set(this: any, value: unknown): void {
75	      this.text = String(value);
76	    },
77	  });
78	  // innerHTML 只记录不解析：意见内容若改走 innerHTML 渲染，textContent 断言会失败，
79	  // innerHTMLAssigned 标记则给出更直接的原因
80	  Object.defineProperty(node, 'innerHTML', {
81	    get(): string {
82	      return '';
83	    },
84	    set(this: any, value: unknown): void {
85	      this.innerHTMLAssigned = true;
86	    },
87	  });
88	  return node as El;
89	}
