97	function gate(): Gate {
98	  let resolve!: (value: unknown) => void;
99	  let reject!: (error: Error) => void;
100	  const promise = new Promise<unknown>((res, rej) => {
101	    resolve = res;
102	    reject = rej;
103	  });
104	  return { promise, resolve, reject };
105	}
