158	  constructor(script: string) {
159	    const byId: Map<string, El> = new Map();
160	    const register = (id: string, tag: string, hidden = false): El => {
161	      const node = makeElement(tag);
162	      node.hidden = hidden;
163	      byId.set(id, node);
164	      this.els[id] = node;
165	      return node;
166	    };
