  const text = char.repeat(n);
  assert.equal(points(text), n);
  return text;
}

// 一条三字段都符合当前规则的正常旧记录
function normalIdea(overrides: Partial<Idea> = {}): Idea {
  return {
    id: 'normal-1',
    title: '普通意见',
    description: '这是一条各字段都在当前限制内的普通意见。',
    scenario: '日常使用',
    createdAt: '2024-02-03T04:05:06.000Z',
    ...overrides,
  };
}

